+                divisor,
+                writable!(divisor),
+                ExtendKind::Signed(Extend::<Signed>::I64Extend32),
+            );
+            self.extend(
+                dividend,
+                writable!(dividend),
+                ExtendKind::Signed(Extend::<Signed>::I64Extend32),
+            );
+            OperandSize::S64
+        } else {
+            size
+        };
+
+        let op = match kind {
+            RemKind::Signed => ALUOp::SDiv,
+            RemKind::Unsigned => ALUOp::UDiv,
+        };
+
+        self.alu_rrr(op, divisor, dividend, scratch, size);
+
+        self.alu_rrrr(
+            ALUOp3::MSub,
+            scratch.to_reg(),
+            divisor,
+            dest.map(Into::into),
+            dividend,
+            size,
+        );
+    }
