+    /// Set value in dst to `0` or `1` based on flags in status register and
+    /// [`CmpKind`].
+    pub fn setcc(&mut self, kind: IntCmpKind, dst: WritableReg) {
+        self.setcc_impl(kind.into(), dst);
+    }
