+                            masm.asm.mov_ir(scratch.writable(), v, v.size());
+                            masm.asm.and_rrr(scratch.inner(), rn, rd, size);
+                        });
+                    }
+                };
+
+                Ok(())
+            }
+
+            (RegImm::Reg(rm), rn, rd) => {
+                self.asm.and_rrr(rm, rn, rd, size);
+                Ok(())
+            }
+        }
+    }
