+                Ok(())
+            }
+        }
+    }
+
+    fn xor(&mut self, dst: WritableReg, lhs: Reg, rhs: RegImm, size: OperandSize) -> Result<()> {
+        match (rhs, lhs, dst) {
+            (RegImm::Imm(v), rn, rd) => {
