+        self.with_scratch::<FloatScratch, _>(|masm, tmp| {
+            masm.v128_and(src1, mask, tmp.writable())?;
+            masm.v128_and_not(mask, src2, dst)?;
+            masm.v128_or(dst.to_reg(), tmp.inner(), dst)?;
